esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// Gauge, in seconds: the age of the longest running transaction. MAX_OVER_TIME() catches
// the peak within the window rather than whatever happened to be open at the last scrape.
| STATS
    `Longest Transaction (s)` = MAX(MAX_OVER_TIME(pg_stat_activity_xact_runtime)),
    `WAL Size (MB)` = MAX(LAST_OVER_TIME(pg_wal_size_mb))
  BY resource.attributes.supabase_project_ref
// 900s = 15 minutes. Lower to 300 for OLTP-only projects; raise if you run batch jobs.
| WHERE `Longest Transaction (s)` > 900
| SORT `Longest Transaction (s)` DESC
